<script setup>
import ListPagination from '../shared/components/ListPagination.vue'
import {ref,computed,watch} from 'vue'

import {toast} from '../shared/composables/toast.js'
const props=defineProps({service:String,environment:String,snapshots:{type:Array,default:()=>[]},compareId:[String,Number],base:[String,Number]})
const emit=defineEmits(['open'])
const visible=ref(false),loading=ref(false),comparison=ref(null),baseID=ref(0),active=ref('operations'),selected=ref(null),search=ref(''),kind=ref('')
const labels={added:'新增',removed:'删除',modified:'修改'},colors={added:'green',removed:'red',modified:'orange'}
let epoch=0,target=0
const changes=computed(()=>(comparison.value?.changes||[]).filter(c=>(!kind.value||c.kind===kind.value)&&`${c.path} ${c.method} ${c.summary}`.toLowerCase().includes(search.value.toLowerCase())))
const baseOptions=computed(()=>{const list=[...props.snapshots];if(comparison.value?.baseline.id&&!list.some(s=>s.id===comparison.value.baseline.id))list.push(comparison.value.baseline);return [{value:0,label:'空基线（首次文档）'},...list.filter(s=>s.id<target&&s.environment===comparison.value?.snapshot.environment).map(s=>({value:s.id,label:'#'+s.id+' · '+(s.run_id?'构建 #'+s.run_id:s.provider==='openapi-edit'?'手动编辑':'手动导入')}))]})
async function load(id,base){const seq=++epoch;loading.value=true;selected.value=null;active.value='operations';try{const r=await fetch('api/api-documents/'+id+'/comparison?'+new URLSearchParams({service:props.service,...(base==null?{}:{base_id:String(base)})})),v=await r.json();if(!r.ok)throw Error(v.error||'对比读取失败');if(seq!==epoch)return;comparison.value=v;baseID.value=v.baseline.id||0}catch(e){if(seq===epoch)toast(e.message,'error')}finally{if(seq===epoch)loading.value=false}}
function compare(record){target=record.id;comparison.value=null;search.value='';kind.value='';visible.value=true;load(record.id)}
function fields(record){selected.value=record;active.value='fields'}
function openDefinition(record){const id=record.kind==='removed'?comparison.value.baseline.id:comparison.value.snapshot.id;visible.value=false;emit('open',id,record.id)}
watch(()=>[props.service,props.environment],()=>{epoch++;visible.value=false;comparison.value=null})
watch(()=>[props.service,props.compareId,props.base],()=>{const id=Number(props.compareId);if(!props.service||!(id>0))return;target=id;visible.value=true;comparison.value=null;load(id,props.base==null?undefined:Number(props.base))},{immediate:true})

import OptionPicker from '../shared/components/OptionPicker.vue'

import {ref as _viewRef} from 'vue'
const _view1=_viewRef(1),_view1Size=_viewRef(20)
const _view2=_viewRef(1),_view2Size=_viewRef(20)
const _view3=_viewRef(1),_view3Size=_viewRef(20)


import {Badge,Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Sheet,SheetContent,SheetDescription,SheetFooter,SheetHeader,SheetTitle,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsContent,TabsList,TabsTrigger} from '../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
watch([search,kind],()=>_view2.value=1)
watch(selected,()=>_view3.value=1)
</script>
<template><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:950}).y?({x:950}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:950}).x||({x:950}).minWidth||1010)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(190)+'px'}">快照 / 来源</TableHead><TableHead :style="{width:(110)+'px'}">环境</TableHead><TableHead :style="{width:(220)+'px'}">Commit / 制品</TableHead><TableHead>接口变化</TableHead><TableHead :style="{width:(210)+'px'}">生成时间</TableHead><TableHead :style="{width:(130)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (snapshots||[]).slice((_view1-1)*(_view1Size),_view1*(_view1Size))" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="emit('open',record.id)" variant="ghost" size="default" type="button">#{{record.id}} · {{record.run_id?'构建 #'+record.run_id:record.provider==='openapi-edit'?'手动编辑':'手动导入'}}</Button></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.environment||'未区分环境'}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><code>{{record.commit?.slice(0,12)||'未关联 Commit'}}</code><div>{{record.artifact_id?'制品 #'+record.artifact_id:'未关联制品'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge v-if="record.compared===false" variant="secondary">历史快照，查看对比</Badge><div v-else class="flex flex-wrap items-center gap-2"><Badge :variant="(&quot;green&quot;)==='red'?'destructive':'secondary'">新增 {{record.changes?.added||0}}</Badge><Badge :variant="(&quot;red&quot;)==='red'?'destructive':'secondary'">删除 {{record.changes?.removed||0}}</Badge><Badge :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">修改 {{record.changes?.modified||0}}</Badge></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><span style="white-space:nowrap">{{new Date(record.created_at*1000).toLocaleString()}}</span></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="compare(record)" variant="ghost" size="default" type="button">查看对比</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(snapshots||[]).length"><TableCell :colspan="6"><Empty><EmptyHeader><EmptyDescription>{{"当前环境暂无文档历史"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><ListPagination :page="_view1" :total="(snapshots||[]).length" :page-size="_view1Size" @update:page="_view1=$event;" @update:page-size="_view1Size=$event;_view1=1" :disabled="loading"/></div><Sheet :open="visible" @update:open="async v=>{if(!v){visible=false;epoch++}}"><SheetContent class="data-[side=right]:w-full gap-0 overflow-hidden p-0 data-[side=right]:sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof ('min(1150px,100vw)')==='number'?('min(1150px,100vw)')+'px':('min(1150px,100vw)')}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><SheetHeader class="shrink-0 border-b p-5 pr-12"><SheetTitle>接口文档变更对比</SheetTitle><SheetDescription class="sr-only">详情与操作</SheetDescription></SheetHeader><div class="min-h-0 flex-1 overflow-auto p-5"><div style="width:100%" class="relative min-w-0" :aria-busy="loading"><div v-if="loading" class="flex items-center justify-center gap-2 p-4" role="status"><Spinner/><span class="sr-only">正在读取</span></div><template v-if="comparison"><div class="compare-toolbar"><Badge variant="secondary">{{comparison.snapshot.environment||'未区分环境'}}</Badge><span>快照 #{{comparison.snapshot.id}} 对比</span><OptionPicker v-model="baseID" :disabled="loading" aria-label="文档对比基线" style="width:260px" @change="value=>load(target,value)" :options="baseOptions"/></div><div class="compare-summary flex flex-wrap items-center gap-2"><Badge :variant="(&quot;green&quot;)==='red'?'destructive':'secondary'">新增 {{comparison.summary.added}}</Badge><Badge :variant="(&quot;red&quot;)==='red'?'destructive':'secondary'">删除 {{comparison.summary.removed}}</Badge><Badge :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">修改 {{comparison.summary.modified}}</Badge><Badge variant="secondary">未变 {{comparison.summary.unchanged}}</Badge><Badge v-if="comparison.truncated" :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">明细已达到展示上限，汇总包含全部接口</Badge></div><Tabs :model-value="active" @update:model-value="active=$event;"><div class="flex min-w-0 items-center gap-2"><TabsList class="h-auto! max-w-full flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;operations&quot;">接口变更</TabsTrigger><TabsTrigger :value="&quot;fields&quot;">字段变化</TabsTrigger></TabsList></div><TabsContent :value="&quot;operations&quot;" force-mount v-show="!(active!==&quot;operations&quot;)" class="min-w-0"><div class="compare-toolbar"><InputGroup style="width:320px" class="min-w-0 "><InputGroupInput v-model="search" placeholder="搜索接口名称、方法或路径" aria-label="搜索文档变更"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="search" :disabled="false" size="icon-xs" aria-label="清空输入" @click="search='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><OptionPicker v-model="kind" aria-label="接口变化类型" style="width:160px" :options="[{value:'',label:'全部变化'},...Object.entries(labels).map(([value,label])=>({value,label}))]"/></div><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({}).y?({}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({}).x||({}).minWidth||435)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(85)+'px'}">变化</TableHead><TableHead>接口</TableHead><TableHead :style="{width:(200)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (changes||[]).slice((_view2-1)*(_view2Size),_view2*(_view2Size))" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Badge :variant="(colors[record.kind])==='red'?'destructive':'secondary'">{{labels[record.kind]}}</Badge></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><b>{{record.method}} {{record.path}}</b><div>{{record.summary}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button v-if="record.kind==='modified'" @click="fields(record)" variant="ghost" size="default" type="button">查看字段</Button><Button @click="openDefinition(record)" variant="ghost" size="default" type="button">接口定义</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(changes||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>{{"没有匹配的接口变化"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><ListPagination :page="_view2" :total="(changes||[]).length" :page-size="_view2Size" @update:page="_view2=$event;" @update:page-size="_view2Size=$event;_view2=1" :disabled="loading"/></div></TabsContent><TabsContent :value="&quot;fields&quot;" force-mount v-show="!(active!==&quot;fields&quot;)" class="min-w-0"><template v-if="selected"><div class="compare-toolbar"><Badge :variant="(colors[selected.kind])==='red'?'destructive':'secondary'">{{labels[selected.kind]}}</Badge><b>{{selected.method}} {{selected.path}}</b><Badge v-if="selected.truncated" :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">字段明细已截断</Badge></div><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({}).y?({}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({}).x||({}).minWidth||0)+'px'}"><TableHeader><TableRow><TableHead v-for="column in [{title:'字段路径',dataIndex:'path',width:540},{title:'原值',slotName:'before'},{title:'新值',slotName:'after'}]" :key="column.dataIndex||column.title" :style="{width:column.width?column.width+'px':undefined}">{{column.title}}</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (selected.fields||[]).slice((_view3-1)*(_view3Size),_view3*(_view3Size))" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell v-for="column in [{title:'字段路径',dataIndex:'path',width:540},{title:'原值',slotName:'before'},{title:'新值',slotName:'after'}]" :key="column.dataIndex||column.title"><template v-for="slotName in [column.slotName]"><template v-if="slotName==='before'"><pre>{{record.before_present?record.before:'（不存在）'}}</pre></template><template v-if="slotName==='after'"><pre>{{record.after_present?record.after:'（不存在）'}}</pre></template><template v-if="!column.slotName">{{record[column.dataIndex]}}</template></template></TableCell></TableRow></template><TableRow v-if="!(selected.fields||[]).length"><TableCell :colspan="([{title:'字段路径',dataIndex:'path',width:540},{title:'原值',slotName:'before'},{title:'新值',slotName:'after'}]).length"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div><ListPagination :page="_view3" :total="(selected.fields||[]).length" :page-size="_view3Size" @update:page="_view3=$event;" @update:page-size="_view3Size=$event;_view3=1" :disabled="loading"/></div></template><Empty v-else><EmptyHeader><EmptyDescription>{{"先在接口变更中选择“查看字段”"}}</EmptyDescription></EmptyHeader></Empty></TabsContent></Tabs></template></div></div></SheetContent></Sheet></template>
<style scoped>.compare-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}.compare-summary{margin-bottom:16px}pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font:.75rem/1.6 var(--mono)}code{font-family:var(--mono)}</style>
